package scalus.uplc.jit

import scalus.cardano.ledger.ExUnits
import scalus.uplc.DefaultFun
import scalus.uplc.eval.*
import scalus.uplc.eval.ExBudgetCategory.{BuiltinApp, Startup, Step}

/** The machine-step spends of JIT-compiled code, as plain Scala methods.
  *
  * Generated code calls one of these per site, for example `JitBudget.spendVar(budget, params)`,
  * instead of inlining `budget.spendBudget(Step(StepKind.Var), params.machineCosts.varCost, Nil)`.
  * A call is three bytecode instructions; the inlined form was about 64 % of the generated bytecode
  * and allocated a `Step` per spend. HotSpot inlines these small methods into the generated code.
  * The categories are allocated once, here; `TallyingBudgetSpender` keys on category equality, so
  * it sees the same categories as from the CEK machine.
  *
  * Each method spends what `Cek.scala` `computeCek` spends for one term of its kind.
  */
object JitBudget {

    private val ConstStep = Step(StepKind.Const)
    private val VarStep = Step(StepKind.Var)
    private val LamAbsStep = Step(StepKind.LamAbs)
    private val ApplyStep = Step(StepKind.Apply)
    private val DelayStep = Step(StepKind.Delay)
    private val ForceStep = Step(StepKind.Force)
    private val BuiltinStep = Step(StepKind.Builtin)
    private val ConstrStep = Step(StepKind.Constr)
    private val CaseStep = Step(StepKind.Case)

    /** `BuiltinApp(fun)` of every builtin, indexed by `DefaultFun.ordinal`. */
    private val BuiltinAppCategory: Array[ExBudgetCategory] = DefaultFun.values.map(BuiltinApp(_))

    /** The startup cost, spent once per evaluation, as `Cek.scala` `evaluateTerm`. */
    def spendStartup(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(Startup, p.machineCosts.startupCost, Nil)

    /** The cost of a saturated builtin `fun`, as `Cek.scala` `evalBuiltinApp` spends it, before the
      * builtin runs. Called by the hand-written builtins and the bridge, not by generated code.
      */
    def spendBuiltinApp(b: BudgetSpender, fun: DefaultFun, cost: ExUnits): Unit =
        b.spendBudget(BuiltinAppCategory(fun.ordinal), cost, Nil)

    def spendConst(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(ConstStep, p.machineCosts.constCost, Nil)

    def spendVar(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(VarStep, p.machineCosts.varCost, Nil)

    def spendLamAbs(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(LamAbsStep, p.machineCosts.lamCost, Nil)

    def spendApply(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(ApplyStep, p.machineCosts.applyCost, Nil)

    def spendDelay(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(DelayStep, p.machineCosts.delayCost, Nil)

    def spendForce(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(ForceStep, p.machineCosts.forceCost, Nil)

    def spendBuiltin(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(BuiltinStep, p.machineCosts.builtinCost, Nil)

    def spendConstr(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(ConstrStep, p.machineCosts.constrCost, Nil)

    def spendCase(b: BudgetSpender, p: MachineParams): Unit =
        b.spendBudget(CaseStep, p.machineCosts.caseCost, Nil)

    /** A let-binding `[(lam x body) arg]`: the Apply step, then the LamAbs step of the function, in
      * the order the CEK machine spends them before it computes `arg`.
      */
    def spendLet(b: BudgetSpender, p: MachineParams): Unit = {
        spendApply(b, p)
        spendLamAbs(b, p)
    }

    /** A saturated builtin application `[(force^nForce (builtin f)) a1 .. a_nApply]`, up to its
      * arguments: `nApply` Apply steps, `nForce` Force steps, then the Builtin step. The CEK
      * machine spends them in this order while it walks down to the builtin, before it computes the
      * arguments.
      */
    def spendSaturated(b: BudgetSpender, p: MachineParams, nApply: Int, nForce: Int): Unit = {
        var i = 0
        while i < nApply do
            spendApply(b, p)
            i += 1
        i = 0
        while i < nForce do
            spendForce(b, p)
            i += 1
        spendBuiltin(b, p)
    }
}
